// Encode the vendored Carbon SVGs as theme-colored CSS masks. No network or
// icon package install is needed to build or run the extension.
const fs = require('node:fs');
const path = require('node:path');

const directory = path.join(__dirname, '..', 'media', 'vendor', 'carbon-icons');
const manifest = JSON.parse(fs.readFileSync(path.join(directory, 'manifest.json'), 'utf8'));
const icons = Object.entries(manifest.icons);
const variables = icons.map(([name, source]) => {
    const svg = fs.readFileSync(path.join(directory, source), 'utf8').trim();
    return `    --md-icon-${name}: url("data:image/svg+xml,${encodeURIComponent(svg)}");`;
});
const classes = icons.map(([name]) => `.md-icon--${name} { --md-icon: var(--md-icon-${name}); }`);

fs.writeFileSync(path.join(directory, 'icons.css'), `/*
 * Carbon Icons ${manifest.version} — Copyright IBM Corp. 2016, 2023.
 * Apache-2.0; see LICENSE and README.md in this directory.
 * Generated by scripts/bundle-icons.js. SVG artwork is unchanged;
 * ManulDown adds CSS masks, theme color inheritance, and class names.
 */
body {
${variables.join('\n')}
}

.md-icon {
    display: inline-block;
    width: var(--md-ui-icon-size, 16px);
    height: var(--md-ui-icon-size, 16px);
    flex-shrink: 0;
    vertical-align: middle;
    background-color: currentColor;
    -webkit-mask: var(--md-icon) center / contain no-repeat;
    mask: var(--md-icon) center / contain no-repeat;
    pointer-events: none;
    forced-color-adjust: none;
}

${classes.join('\n')}
`);
